use crate::structure::{OrganismStructure,PhysicalConstituentId};
use serde::{Deserialize,Serialize};
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq,Eq)]pub struct CoreIntegrity{pub unit_indices:[usize;6]}
impl CoreIntegrity{pub fn new(unit_indices:[usize;6])->Option<Self>{let mut sorted=unit_indices;sorted.sort_unstable();if sorted.windows(2).any(|pair|pair[0]==pair[1]){return None}Some(Self{unit_indices})}pub fn is_intact(&self,structure:&OrganismStructure)->bool{if self.unit_indices.iter().any(|&index|index>=structure.units.len()){return false}let core_ids:Vec<PhysicalConstituentId>=self.unit_indices.iter().filter_map(|&index|structure.physical_id(index)).collect();if core_ids.len()!=6{return false}for &unit_id in &core_ids{let core_bond_count=structure.bonds.iter().filter(|bond|{let other=if bond.endpoint_a.constituent_id==unit_id{Some(bond.endpoint_b.constituent_id)}else if bond.endpoint_b.constituent_id==unit_id{Some(bond.endpoint_a.constituent_id)}else{None};other.map_or(false,|other|core_ids.contains(&other))}).count();if core_bond_count<2{return false}}let components=structure.connected_components();components.iter().any(|component|self.unit_indices.iter().all(|unit|component.contains(unit)))}}
#[cfg(test)]mod tests{use super::*;use crate::structure::{Bond,BondEndpoint,ConnectionEndpoint,Placement,StructuralUnit};fn structure_with_six_core_units()->OrganismStructure{let mut structure=OrganismStructure::new();for i in 0..6{structure.add_unit(StructuralUnit::new("Carbon",Placement{x:i as f64,y:0.0,rotation_radians:0.0}));}for i in 0..6{let a=structure.physical_id(i).unwrap();let b=structure.physical_id((i+1)%6).unwrap();structure.push_bond_unchecked(Bond{endpoint_a:BondEndpoint::new(a,ConnectionEndpoint::Corner{point_index:0}),endpoint_b:BondEndpoint::new(b,ConnectionEndpoint::Corner{point_index:1}),strength:0.8,bond_energy:1.0});}structure}#[test]fn six_unique_units_create_valid_core_integrity(){assert!(CoreIntegrity::new([0,1,2,3,4,5]).is_some());assert!(CoreIntegrity::new([0,1,2,3,4,4]).is_none())}#[test]fn intact_closed_core_passes(){let structure=structure_with_six_core_units();let integrity=CoreIntegrity::new([0,1,2,3,4,5]).unwrap();assert!(integrity.is_intact(&structure))}#[test]fn breaking_one_core_bond_fails_integrity(){let mut structure=structure_with_six_core_units();structure.break_bond(0);let integrity=CoreIntegrity::new([0,1,2,3,4,5]).unwrap();assert!(!integrity.is_intact(&structure))}#[test]fn missing_core_unit_fails_integrity(){let mut structure=structure_with_six_core_units();structure.units.pop();let integrity=CoreIntegrity::new([0,1,2,3,4,5]).unwrap();assert!(!integrity.is_intact(&structure))}#[test]fn external_bond_does_not_break_core_integrity(){let mut structure=structure_with_six_core_units();let external=structure.add_unit(StructuralUnit::new("Carbon",Placement{x:10.0,y:0.0,rotation_radians:0.0}));let core=structure.physical_id(0).unwrap();let external_id=structure.physical_id(external).unwrap();structure.push_bond_unchecked(Bond{endpoint_a:BondEndpoint::new(core,ConnectionEndpoint::Corner{point_index:2}),endpoint_b:BondEndpoint::new(external_id,ConnectionEndpoint::Corner{point_index:0}),strength:0.4,bond_energy:0.5});let integrity=CoreIntegrity::new([0,1,2,3,4,5]).unwrap();assert!(integrity.is_intact(&structure))}}
